function minimumLength(s) {
  const count = new Array(26).fill(0);
  for (const letter of s) {
    count[letter.charCodeAt(0) - 97]++;
  }

  let kept = 0;
  for (const freq of count) {
    if (freq === 0) {
      continue;
    }
    kept += freq % 2 === 1 ? 1 : 2;
  }
  return kept;
}

