function minimumLength(s) {
  // Explore every string reachable by any sequence of moves and keep the shortest.
  const seen = new Set([s]);
  const stack = [s];
  let best = s.length;
  while (stack.length > 0) {
    const current = stack.pop();
    best = Math.min(best, current.length);
    for (let i = 0; i < current.length; i++) {
      let l = i - 1;
      while (l >= 0 && current[l] !== current[i]) l--;
      let r = i + 1;
      while (r < current.length && current[r] !== current[i]) r++;
      if (l < 0 || r >= current.length) continue;
      const next = current.slice(0, l) + current.slice(l + 1, r) + current.slice(r + 1);
      if (!seen.has(next)) {
        seen.add(next);
        stack.push(next);
      }
    }
  }
  return best;
}

