function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  if (size === 'large') {
    // Up to 10,000 letters over a random alphabet; skewed picks give the letters very different counts.
    const n = int(9000, 10000);
    const k = int(1, 26);
    const skew = rand() < 0.5;
    let s = '';
    for (let i = 0; i < n; i++) s += letters[Math.floor(k * (skew ? rand() * rand() : rand()))];
    return [s];
  }
  // Short strings over 1 to 4 letters, so letters repeat and the brute force can try every move.
  const n = int(1, 10);
  const k = int(1, 4);
  const offset = int(0, 26 - k);
  let s = '';
  for (let i = 0; i < n; i++) s += letters[offset + int(0, k - 1)];
  return [s];
}
